insert into pg_temp.school967_civic_edition(payload) values ($school_civic_edition$[{"slug":"how-state-works","index":0,"old_lessons":[{"title":"الفكرة الأساسية","body":"الدولة تنظيم سياسي له سكان وإقليم ومؤسسات تمارس السلطة؛ أما السيادة فتصف استقلال القرار العام ضمن قواعد القانون الدولي. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"سيادة","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة. جرّب تحليل الموقف بهذا الترتيب: حدد الإقليم ← حدد المؤسسات ← ميز بين الاختصاص الداخلي والخارجي. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد الإقليم ← حدد المؤسسات ← ميز بين الاختصاص الداخلي والخارجي","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا تعني السيادة أن جميع قرارات الحكومة مباحة أو أنها خارج الالتزامات القانونية الدولية. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"الدولة تنظيم سياسي له سكان وإقليم ومؤسسات تمارس السلطة؛ أما السيادة فتصف استقلال القرار العام ضمن قواعد القانون الدولي. حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة.","lessons":[{"title":"من الصفر: ما معنى الفكرة؟","body":"الدولة تنظيم سياسي له سكان وإقليم ومؤسسات تمارس السلطة؛ أما السيادة فتصف استقلال القرار العام ضمن قواعد القانون الدولي.\n\nقد توجد وزارة أو مجلس بلدي داخل دولة، لكن المؤسسة وحدها ليست دولة. اسأل دائمًا: من يضع القواعد العامة، وعلى أي إقليم تسري، ومن يمثل الدولة خارجيًا؟","example":"سيادة","note":"ابدأ باستيعاب معنى المصطلح، ثم اربطه بالسؤال أو الموقف الذي يشرحه."},{"title":"موقف من الحياة: كيف تعمل الفكرة؟","body":"حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة.\n\nقد توجد وزارة أو مجلس بلدي داخل دولة، لكن المؤسسة وحدها ليست دولة. اسأل دائمًا: من يضع القواعد العامة، وعلى أي إقليم تسري، ومن يمثل الدولة خارجيًا؟","example":"حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة.","note":"اقرأ الحالة، وسمِّ الجهة أو العلاقة أو الرقم الذي يمثل الفكرة الأساسية."},{"title":"كيف تحلل المشكلة خطوة بخطوة؟","body":"لنطبّق ما فهمناه على هذه الحالة: حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة.\n\nاتبع تسلسل التفكير الموضح أدناه، وتحقق مما تعرفه قبل الانتقال إلى الخطوة التالية. قد توجد وزارة أو مجلس بلدي داخل دولة، لكن المؤسسة وحدها ليست دولة. اسأل دائمًا: من يضع القواعد العامة، وعلى أي إقليم تسري، ومن يمثل الدولة خارجيًا؟","example":"حدد الإقليم ← حدد المؤسسات ← ميز بين الاختصاص الداخلي والخارجي","note":"اتبع كل خطوة بالترتيب؛ المهم أن تفهم لماذا تأتي هذه الخطوة هنا."},{"title":"تمييز مهم: متى لا تكفي المعلومة؟","body":"لا تعني السيادة أن جميع قرارات الحكومة مباحة أو أنها خارج الالتزامات القانونية الدولية.\n\nقد توجد وزارة أو مجلس بلدي داخل دولة، لكن المؤسسة وحدها ليست دولة. اسأل دائمًا: من يضع القواعد العامة، وعلى أي إقليم تسري، ومن يمثل الدولة خارجيًا؟","example":"توقف واسأل: هل يكفي هذا المثال لفهم «الدولة والسيادة» في كل بلد أو حالة؟","note":"فهم حدود المثال جزء من التعلم. لا نعمم نتيجة حالة واحدة على جميع الحالات."}],"intro":"في هذه المحطة سنفهم «الدولة والسيادة» من البداية، من دون افتراض معرفة سابقة.\n\nالدولة تنظيم سياسي له سكان وإقليم ومؤسسات تمارس السلطة؛ أما السيادة فتصف استقلال القرار العام ضمن قواعد القانون الدولي.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة."},{"slug":"how-state-works","index":1,"old_lessons":[{"title":"الفكرة الأساسية","body":"المواطنة رابطة قانونية وسياسية بين الفرد والدولة ترتبط بحقوق وواجبات، وتختلف عن مجرد الإقامة في الإقليم. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"مواطنة","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية. جرّب تحليل الموقف بهذا الترتيب: حدد صفة الشخص ← راجع حقوقه القانونية ← ميز بين الجنسية والإقامة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد صفة الشخص ← راجع حقوقه القانونية ← ميز بين الجنسية والإقامة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا تخلط بين الهوية الثقافية والجنسية القانونية؛ تختلف شروط اكتساب الجنسية بين الدول. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"المواطنة رابطة قانونية وسياسية بين الفرد والدولة ترتبط بحقوق وواجبات، وتختلف عن مجرد الإقامة في الإقليم. قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية.","lessons":[{"title":"من الصفر: ما معنى الفكرة؟","body":"المواطنة رابطة قانونية وسياسية بين الفرد والدولة ترتبط بحقوق وواجبات، وتختلف عن مجرد الإقامة في الإقليم.\n\nيمكن لشخص أن يشارك في المجتمع ويعمل ويدفع ضرائب من دون أن يحمل الجنسية. افصل بين حياة الفرد اليومية وصفته القانونية وحقوقه الانتخابية.","example":"مواطنة","note":"ابدأ باستيعاب معنى المصطلح، ثم اربطه بالسؤال أو الموقف الذي يشرحه."},{"title":"موقف من الحياة: كيف تعمل الفكرة؟","body":"قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية.\n\nيمكن لشخص أن يشارك في المجتمع ويعمل ويدفع ضرائب من دون أن يحمل الجنسية. افصل بين حياة الفرد اليومية وصفته القانونية وحقوقه الانتخابية.","example":"قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية.","note":"اقرأ الحالة، وسمِّ الجهة أو العلاقة أو الرقم الذي يمثل الفكرة الأساسية."},{"title":"كيف تحلل المشكلة خطوة بخطوة؟","body":"لنطبّق ما فهمناه على هذه الحالة: قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية.\n\nاتبع تسلسل التفكير الموضح أدناه، وتحقق مما تعرفه قبل الانتقال إلى الخطوة التالية. يمكن لشخص أن يشارك في المجتمع ويعمل ويدفع ضرائب من دون أن يحمل الجنسية. افصل بين حياة الفرد اليومية وصفته القانونية وحقوقه الانتخابية.","example":"حدد صفة الشخص ← راجع حقوقه القانونية ← ميز بين الجنسية والإقامة","note":"اتبع كل خطوة بالترتيب؛ المهم أن تفهم لماذا تأتي هذه الخطوة هنا."},{"title":"تمييز مهم: متى لا تكفي المعلومة؟","body":"لا تخلط بين الهوية الثقافية والجنسية القانونية؛ تختلف شروط اكتساب الجنسية بين الدول.\n\nيمكن لشخص أن يشارك في المجتمع ويعمل ويدفع ضرائب من دون أن يحمل الجنسية. افصل بين حياة الفرد اليومية وصفته القانونية وحقوقه الانتخابية.","example":"توقف واسأل: هل يكفي هذا المثال لفهم «الشعب والمواطنة» في كل بلد أو حالة؟","note":"فهم حدود المثال جزء من التعلم. لا نعمم نتيجة حالة واحدة على جميع الحالات."}],"intro":"في هذه المحطة سنفهم «الشعب والمواطنة» من البداية، من دون افتراض معرفة سابقة.\n\nالمواطنة رابطة قانونية وسياسية بين الفرد والدولة ترتبط بحقوق وواجبات، وتختلف عن مجرد الإقامة في الإقليم.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية."},{"slug":"how-state-works","index":2,"old_lessons":[{"title":"الفكرة الأساسية","body":"الدستور ينظم شكل الدولة والسلطات وحقوق الأفراد وآليات تعديل القواعد الأساسية وفق نظامها القانوني. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"دستور","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص. جرّب تحليل الموقف بهذا الترتيب: حدد النص الدستوري ← قارن الاختصاصات ← افحص آلية الرقابة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد النص الدستوري ← قارن الاختصاصات ← افحص آلية الرقابة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"وجود دستور مكتوب وحده لا يثبت تطبيق أحكامه؛ يجب فحص الممارسة والمؤسسات والرقابة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"الدستور ينظم شكل الدولة والسلطات وحقوق الأفراد وآليات تعديل القواعد الأساسية وفق نظامها القانوني. إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص.","lessons":[{"title":"من الصفر: ما معنى الفكرة؟","body":"الدستور ينظم شكل الدولة والسلطات وحقوق الأفراد وآليات تعديل القواعد الأساسية وفق نظامها القانوني.\n\nفكر في الدستور كخريطة للصلاحيات لا كملصق شعارات. عند النزاع لا تكفي رغبات المسؤولين؛ يجب الرجوع إلى القواعد التي تحدد من يقرر وكيف.","example":"دستور","note":"ابدأ باستيعاب معنى المصطلح، ثم اربطه بالسؤال أو الموقف الذي يشرحه."},{"title":"موقف من الحياة: كيف تعمل الفكرة؟","body":"إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص.\n\nفكر في الدستور كخريطة للصلاحيات لا كملصق شعارات. عند النزاع لا تكفي رغبات المسؤولين؛ يجب الرجوع إلى القواعد التي تحدد من يقرر وكيف.","example":"إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص.","note":"اقرأ الحالة، وسمِّ الجهة أو العلاقة أو الرقم الذي يمثل الفكرة الأساسية."},{"title":"كيف تحلل المشكلة خطوة بخطوة؟","body":"لنطبّق ما فهمناه على هذه الحالة: إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص.\n\nاتبع تسلسل التفكير الموضح أدناه، وتحقق مما تعرفه قبل الانتقال إلى الخطوة التالية. فكر في الدستور كخريطة للصلاحيات لا كملصق شعارات. عند النزاع لا تكفي رغبات المسؤولين؛ يجب الرجوع إلى القواعد التي تحدد من يقرر وكيف.","example":"حدد النص الدستوري ← قارن الاختصاصات ← افحص آلية الرقابة","note":"اتبع كل خطوة بالترتيب؛ المهم أن تفهم لماذا تأتي هذه الخطوة هنا."},{"title":"تمييز مهم: متى لا تكفي المعلومة؟","body":"وجود دستور مكتوب وحده لا يثبت تطبيق أحكامه؛ يجب فحص الممارسة والمؤسسات والرقابة.\n\nفكر في الدستور كخريطة للصلاحيات لا كملصق شعارات. عند النزاع لا تكفي رغبات المسؤولين؛ يجب الرجوع إلى القواعد التي تحدد من يقرر وكيف.","example":"توقف واسأل: هل يكفي هذا المثال لفهم «الدستور والقواعد العليا» في كل بلد أو حالة؟","note":"فهم حدود المثال جزء من التعلم. لا نعمم نتيجة حالة واحدة على جميع الحالات."}],"intro":"في هذه المحطة سنفهم «الدستور والقواعد العليا» من البداية، من دون افتراض معرفة سابقة.\n\nالدستور ينظم شكل الدولة والسلطات وحقوق الأفراد وآليات تعديل القواعد الأساسية وفق نظامها القانوني.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص."},{"slug":"how-state-works","index":3,"old_lessons":[{"title":"الفكرة الأساسية","body":"الفصل بين السلطات يوزع التشريع والتنفيذ والقضاء بين مؤسسات تختلف صلاحياتها وطرق الرقابة المتبادلة. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"الفصل بين السلطات","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة. جرّب تحليل الموقف بهذا الترتيب: حدد الوظيفة ← عين المؤسسة ← افحص حدود الرقابة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد الوظيفة ← عين المؤسسة ← افحص حدود الرقابة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"الفصل لا يعني انقطاع التواصل الكامل بين السلطات؛ درجات الفصل والتعاون تتفاوت بين الأنظمة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"الفصل بين السلطات يوزع التشريع والتنفيذ والقضاء بين مؤسسات تختلف صلاحياتها وطرق الرقابة المتبادلة. حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة.","lessons":[{"title":"من الصفر: ما معنى الفكرة؟","body":"الفصل بين السلطات يوزع التشريع والتنفيذ والقضاء بين مؤسسات تختلف صلاحياتها وطرق الرقابة المتبادلة.\n\nتخيل ثلاث وظائف: كتابة القاعدة، تنفيذها، ثم الفصل في الخلاف حولها. توزيع الوظائف يساعد على تحديد المسؤولية وطرق المراجعة، ولا يمنع تعاون المؤسسات.","example":"الفصل بين السلطات","note":"ابدأ باستيعاب معنى المصطلح، ثم اربطه بالسؤال أو الموقف الذي يشرحه."},{"title":"موقف من الحياة: كيف تعمل الفكرة؟","body":"حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة.\n\nتخيل ثلاث وظائف: كتابة القاعدة، تنفيذها، ثم الفصل في الخلاف حولها. توزيع الوظائف يساعد على تحديد المسؤولية وطرق المراجعة، ولا يمنع تعاون المؤسسات.","example":"حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة.","note":"اقرأ الحالة، وسمِّ الجهة أو العلاقة أو الرقم الذي يمثل الفكرة الأساسية."},{"title":"كيف تحلل المشكلة خطوة بخطوة؟","body":"لنطبّق ما فهمناه على هذه الحالة: حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة.\n\nاتبع تسلسل التفكير الموضح أدناه، وتحقق مما تعرفه قبل الانتقال إلى الخطوة التالية. تخيل ثلاث وظائف: كتابة القاعدة، تنفيذها، ثم الفصل في الخلاف حولها. توزيع الوظائف يساعد على تحديد المسؤولية وطرق المراجعة، ولا يمنع تعاون المؤسسات.","example":"حدد الوظيفة ← عين المؤسسة ← افحص حدود الرقابة","note":"اتبع كل خطوة بالترتيب؛ المهم أن تفهم لماذا تأتي هذه الخطوة هنا."},{"title":"تمييز مهم: متى لا تكفي المعلومة؟","body":"الفصل لا يعني انقطاع التواصل الكامل بين السلطات؛ درجات الفصل والتعاون تتفاوت بين الأنظمة.\n\nتخيل ثلاث وظائف: كتابة القاعدة، تنفيذها، ثم الفصل في الخلاف حولها. توزيع الوظائف يساعد على تحديد المسؤولية وطرق المراجعة، ولا يمنع تعاون المؤسسات.","example":"توقف واسأل: هل يكفي هذا المثال لفهم «الفصل بين السلطات» في كل بلد أو حالة؟","note":"فهم حدود المثال جزء من التعلم. لا نعمم نتيجة حالة واحدة على جميع الحالات."}],"intr